                // Probe failure FAILS CLOSED: one deferred refresh
                // costs a tick; racing a live leg costs the leg's
                // whole push stream.
                console.warn('  ⚠️  ' + key +
                    ' head-run probe failed — branch refresh deferred (fail closed, gh-798)');
