                        workspace: effectiveRepoInfo.owner,
                        repository: effectiveRepoInfo.repo,
                        number: ticket.prNumber,
                        body: linesUb.join('\n') + '\n\n' +
                            'Cancelled ' + staleCancelledUb.length + ' validation run(s) ' +
